using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new ResearchNotebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        // Simulated web search returning snippet results.
        // Replace this body with a real search API (e.g. Bing Search) for production use.
        var results = new[]
        {
            new SearchResult($"Overview of {query}", $"https://example.com/{Uri.EscapeDataString(query)}",
                $"{query} is a broad topic studied across many disciplines. " +
                $"Recent advances have expanded our understanding significantly."),
            new SearchResult($"{query} - Recent Developments", $"https://research.example.com/{Uri.EscapeDataString(query)}",
                $"In 2025, researchers made breakthroughs in {query}, " +
                "including new frameworks and improved methodologies."),
            new SearchResult($"Practical Applications of {query}", $"https://applied.example.com/{Uri.EscapeDataString(query)}",
                $"The practical applications of {query} span healthcare, " +
                "finance, education, and environmental science."),
        };

        var sb = new StringBuilder();
        foreach (var r in results)
        {
            sb.AppendLine($"**{r.Title}**");
            sb.AppendLine($"  URL: {r.Url}");
            sb.AppendLine($"  Snippet: {r.Snippet}");
            sb.AppendLine();
        }

        return sb.ToString();
    },
    name: "web_search",
    description: "Search the web for information on a topic. Returns titles, URLs, and text snippets.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise research note capturing a key finding")] string note,
     [Description("The source URL for this finding")] string source) =>
    {
        notebook.AddNote(note, source);
        return $"Note #{notebook.Notes.Count} saved.";
    },
    name: "add_note",
    description: "Save a research note with its source URL for later summarization.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        if (notebook.Notes.Count == 0)
            return "No notes taken yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < notebook.Notes.Count; i++)
        {
            var (note, source) = notebook.Notes[i];
            sb.AppendLine($"[{i + 1}] {note}");
            sb.AppendLine($"    Source: {source}");
        }

        return sb.ToString();
    },
    name: "read_notes",
    description: "Read all research notes collected so far.");

// --- Agent setup -------------------------------------------------------------

IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .Build();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic:
        1. Use the web_search tool to find information (search 2-3 times with varied queries).
        2. Use add_note to record each key finding with its source URL.
        3. Use read_notes to review everything you collected.
        4. Provide a final summary with sections: Overview, Key Findings, and Sources.
        Be thorough but concise. Always cite sources.
        """,
    name: "ResearchAgent",
    description: "Researches topics using web search and note-taking tools",
    tools: [searchTool, addNoteTool, readNotesTool]);

// --- Run ---------------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF)        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
    topic = "quantum computing applications in drug discovery";

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var session = new ChatClientAgentSession();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine(response.Text);

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Research complete. {notebook.Notes.Count} notes collected.");
if (response.Usage is { } usage)
{
    Console.WriteLine(
        $"Token usage — Input: {usage.InputTokenCount}, Output: {usage.OutputTokenCount}, Total: {usage.TotalTokenCount}");
}

